#!/usr/bin/env bash
# Generates .env with random local-only secrets for the Docker Compose stack. Never commit .env.
# Usage: scripts/init-local-env.sh [--force]
set -euo pipefail

cd "$(dirname "$0")/.."
ENV_FILE=.env

if [[ -f "$ENV_FILE" && "${1:-}" != "--force" ]]; then
  echo "$ENV_FILE already exists (use --force to regenerate; existing database volumes keep their old passwords)." >&2
  exit 0
fi

secret() { openssl rand -base64 48 | tr -dc 'A-Za-z0-9' | head -c "${1:-32}"; }

umask 077
cat > "$ENV_FILE" <<ENV
# Generated by scripts/init-local-env.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ). LOCAL DEVELOPMENT ONLY - do not commit.
POSTGRES_SUPERUSER_PASSWORD=$(secret)
MEDASSIST_DB_OWNER_PASSWORD=$(secret)
MEDASSIST_DB_APP_PASSWORD=$(secret)
KEYCLOAK_DB_PASSWORD=$(secret)
KEYCLOAK_ADMIN_PASSWORD=$(secret 20)
# Password for the fictional demo users dr.demo, dr.second, admin.demo, km.demo
MEDASSIST_DEMO_USER_PASSWORD=$(secret 16)

# Used when running the backend outside Docker (./mvnw spring-boot:run -Dspring-boot.run.profiles=local)
DB_URL=jdbc:postgresql://localhost:5432/medassist
DB_APP_USER=medassist_app
DB_MIGRATION_USER=medassist_owner

# AI provider (optional): none | openai | azure-openai | openai-compatible
AI_PROVIDER=none
# OPENAI_API_KEY=
# OPENAI_MODEL=
# LOCAL_LLM_BASE_URL=http://host.docker.internal:11434/v1
# LOCAL_LLM_MODEL=
ENV

# The backend's local profile reads DB_APP_PASSWORD / DB_MIGRATION_PASSWORD from this file when run outside Docker.
APP_PW=$(grep '^MEDASSIST_DB_APP_PASSWORD=' "$ENV_FILE" | cut -d= -f2)
OWNER_PW=$(grep '^MEDASSIST_DB_OWNER_PASSWORD=' "$ENV_FILE" | cut -d= -f2)
printf 'DB_APP_PASSWORD=%s\nDB_MIGRATION_PASSWORD=%s\n' "$APP_PW" "$OWNER_PW" >> "$ENV_FILE"

echo "Created $ENV_FILE with random local secrets (mode 600)."
echo "Demo users: dr.demo, dr.second (CLINICIAN), admin.demo (ADMIN), km.demo (KNOWLEDGE_MANAGER)."
echo "Their password is MEDASSIST_DEMO_USER_PASSWORD in $ENV_FILE."
